"""compat/reserved-names.yaml (CG6, SUTRA_EXPANSION 6.2): every name a registered customer's profile declares, from the entries of
spec/1/rachana.lang.json whose profile is not Core. `--check` exits 1 when the committed file is stale; no flag writes nothing."""
import argparse, json, sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
HEAD = """# Copyright (c) 2026 Ashutosh Sinha. Proprietary: see LICENSE.
#
# Generated by tools/regime/reserved_names.py from spec/1/rachana.lang.json: the names the Drishti profile declares (entries whose
# profile is not Core). Core claims one only through an entry in compat/promotions.yaml naming the level. Do not edit.
customer: drishti
"""


def is_core(p):
    return p == "core" or (isinstance(p, list) and "core" in p)


def build():
    d = json.loads((ROOT / "spec/1/rachana.lang.json").read_text(encoding="utf-8"))
    cats = {}
    for cat, v in d.items():
        if isinstance(v, list):
            for x in v:
                if isinstance(x, dict) and not is_core(x.get("profile")) and "profile" in x:
                    cats.setdefault(cat, set()).add(x.get("name", x.get("code")))
    for place, v in d["keys"].items():
        for x in v:
            if not is_core(x.get("profile")):
                cats.setdefault("keys", set()).add(f"{place}.{x['name']}")
    out = HEAD
    for cat in sorted(cats):
        out += f"{cat}:\n" + "".join(f'  - "{n}"\n' for n in sorted(cats[cat]))
    return out


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--write", action="store_true")
    ap.add_argument("--check", action="store_true")
    a = ap.parse_args()
    text, f = build(), ROOT / "compat/reserved-names.yaml"
    if a.write:
        f.write_text(text, encoding="utf-8")
    elif a.check and (not f.exists() or f.read_text(encoding="utf-8") != text):
        sys.exit("compat/reserved-names.yaml is stale: python3 tools/regime/reserved_names.py --write")
    else:
        print(text if not a.check else "reserved-names.yaml is current")
